---列表刷新
function OverseaStoreSkinCommonNode:OnGetItemByIndex(listView, index)
    if index < 0 then return nil end
    
    local luaIdx = index + 1
    local cell = listView:NewListViewItem("OverseaMallSkinActivityShopSpecialCell")
    local cellData = self:GetProducts()[luaIdx]
    local selectedIdx = self:GetSelectedTabIdx()
    local storeType = self:GetStoreType()
    local scr = CfUtils.GetLuaScr(cell, OverseaStoreConstants.ScrPath.OverseaStoreSkinCommonCell)
    if scr then
        scr:RefreshCell(storeType, cellData, luaIdx, luaIdx == selectedIdx, Bind(self, self.TabOnClickHandler))
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            scr:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            scr:PlayAnimByIdle()
        end
    end
    return cell
end

