---购买点击回调
function OverseaStoreSkinCommonNode:BtnBuyOnClickHandler()
    local storeType = self:GetStoreType()
    local data = self:GetProducts()[self:GetSelectedTabIdx()]

    if storeType == OverseaStoreConstants.StoreType.SkinScene then
        -- 未获得皮肤时，禁止购买场景
        local goodsId = data.icon
        local goodsConf = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if goodsConf then
            local skinId = goodsConf.skinId
            if not CardSkinComponent:IsHasSkin(skinId) then
                GameUtils.Toast(localize("请先购买对应时装"))
                return
            end
        end
    end
    
    if checkInt(data.price) > 0 then
        OverseaStoreMgr:SDKBuyRequest(data)
    else
        local storeType = self:GetStoreType()
        local consume = clone(data.prices)
        for _, v in pairs(consume) do
            v.goodsId = v.currency
            v.num = v.current
        end
        local _, errTip = GoodsUtils.CheckGoodConsume(consume)
        if errTip then
            if consume[1].goodsId == Constants.Currency.PayDiamondId then
                local productVo = GoodsConfMgr:GetInstance():GetGoodsVoById(consume[1].goodsId)
                ServerDifferenceMgr:WrapPrimaryCurrencyBuy({currency = consume[1].goodsId,current = consume[1].num, productName = productVo.name})
            elseif checkNumber(data.ifExchange) == 1 then
                local haveGoodsNum = GoodsUtils.GetThingNo(consume[1].goodsId)
                local itemId, itemNum = ActivityMgr:GetGoodsPrice(consume[1].goodsId)
                local needNum =  consume[1].num - haveGoodsNum
                local youHave = GoodsUtils.GetThingNo(itemId)
                local consumeCount = needNum * itemNum
                local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
                if ServerDifferenceMgr:IsSecondaryCurrencyEnable() or youHave >= consumeCount then
                    ---@type CommonCurrencyExchangePopup.InputData
                    local data = {
                        leftId = itemId,
                        leftNum = consumeCount,
                        rightId = consume[1].goodsId,
                        rightNum = needNum,
                        onConfirmClick = function()
                            OverseaStoreMgr:BuyRequest(storeType, data.productId, 1, data.prices[1])
                        end,
                    }
                    ServerDifferenceMgr:OpenCurrencyExchangePopup(data)
                else
                    GoodsUtils.CheckConsumeDataCondition({{goodsId = consume[1].goodsId , num = consume[1].num}})
                end
            else
                GameUtils.Toast(errTip)
            end
        else
            local prices = checkTable(data.prices)
            local goodsId = prices[1].currency
            local goodsNum = prices[1].current
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local tips = localize('是否花费<color=#E71F55>_num1__name1_</color>购买？', {_num1_ = goodsNum, _name1_ = goodsVo.name})
            GameUtils.SecondConfirm(tips, function()
                OverseaStoreMgr:BuyRequest(storeType, data.productId, 1, data.prices[1])
            end)
        end
    end
end

