---刷新背景
function OverseaStoreSkinCommonNode:RefreshBg()
    local storeType = self:GetStoreType()
    local data = self:GetProducts()[self:GetSelectedTabIdx()]
    if storeType == OverseaStoreConstants.StoreType.SkinCard then
        Events.Broadcast(Constants.EventNames.OVERSEA_STORE_SHOW_SKIN, CfUtils.GetImageFullPath(data.showImage2))
        CfUtils.SetActive(self.OverseaMallSkinSceneEntryNode, false)
    elseif storeType == OverseaStoreConstants.StoreType.SkinBundle then
        local showVideos =  string.split(data.showVideo , ":")
        if table.count(showVideos) > 1 then
            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_SHOW_SKIN, CfUtils.GetImageFullPath(data.showVideo))    
            CfUtils.SetActive(self.OVERSEA_STORE_SHOW_SKIN, false)
        else
            local path = string.format('Movie/%s.usm', data.showVideo)
            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_PLAY_VIDEO, path)    
            CfUtils.SetActive(self.OverseaMallSkinSceneEntryNode, false)
        end
    elseif storeType == OverseaStoreConstants.StoreType.SkinScene then
        CfUtils.SetActive(self.OverseaMallSkinSceneEntryNode, true)
    end
end

---刷新左侧面板
function OverseaStoreSkinCommonNode:RefreshLeftPanel()
    local storeType = self:GetStoreType()
    local data = self:GetProducts()[self:GetSelectedTabIdx()]
    local goodsVo = GoodsConfMgr:GetGoodsVoById(data.icon)
    CfUtils.FillText(self.TextDesc, goodsVo.name)
    if isNotNull(data.specialLogo) and data.specialLogo ~= '' then
        CfUtils.SetActive(self.ImgCopyright, true)
        CfUtils.FillImage(self.ImgCopyright, data.specialLogo)
    else
        CfUtils.SetActive(self.ImgCopyright, false)
    end    
    
    if storeType == OverseaStoreConstants.StoreType.SkinBundle then
        CfUtils.SetActive(self.BtnSkinExplain, true)
        CfUtils.SetActive(self.BtnSceneExplain, true)
        CfUtils.SetActive(self.BtnTryOut, true)
        CfUtils.SetUISwitchImage(self.ImgSymbol, 1)
        local skinId = nil
        local sceneId = nil
        for i, v in ipairs(data.rewards) do
            local goodsType = GoodsUtils.GetIdType(v.goodsId)
            if goodsType == Constants.IDType.Live3DGoods then
                sceneId = checkInt(v.goodsId)
            elseif goodsType ==  Constants.IDType.CardSkin then
                skinId = checkInt(v.goodsId)
            end
        end
        
        local skinGoodsVo = GoodsConfMgr:GetGoodsVoById(skinId)
        if skinGoodsVo then
            CfUtils.FillImage(self.BtnSkinExplainImgHead, skinGoodsVo.photoPath)
        else
            CfUtils.SetActive(self.BtnSkinExplain, false)
        end
        
        local sceneGoodsVo = GoodsConfMgr:GetGoodsVoById(sceneId)
        if sceneGoodsVo then
            CfUtils.FillImage(self.BtnSceneExplainImgScene, sceneGoodsVo.photoPath)
        else
            CfUtils.SetActive(self.BtnSceneExplain, false)
        end
        
    elseif storeType == OverseaStoreConstants.StoreType.SkinCard then
        CfUtils.SetActive(self.BtnSkinExplain, false)
        CfUtils.SetActive(self.BtnSceneExplain, false)
        CfUtils.SetActive(self.BtnTryOut, true)
        CfUtils.SetUISwitchImage(self.ImgSymbol, 1)
    elseif storeType == OverseaStoreConstants.StoreType.SkinScene then
        CfUtils.SetActive(self.BtnSkinExplain, false)
        CfUtils.SetActive(self.BtnSceneExplain, false)
        CfUtils.SetActive(self.BtnTryOut, true)
        CfUtils.SetUISwitchImage(self.ImgSymbol, 2)

        local goodsId = data.icon
        local goodsConf = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if goodsConf then
            local skinId = goodsConf.skinId
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
            CfUtils.FillImage(self.ImgHead, skinVo.buffHead)
            CfUtils.FillImage(self.ImgScene, goodsConf.storeIcon)
        end
    end
end

