---刷新价格
function OverseaStoreSkinCommonNode:RefreshPrice()
    local data = self:GetProducts()[self:GetSelectedTabIdx()]
    local storeType = self:GetStoreType()
    local isOwned = false
    if storeType == OverseaStoreConstants.StoreType.SkinCard then
        isOwned = CardSkinComponent:IsHasSkin(data.icon)
    elseif storeType == OverseaStoreConstants.StoreType.SkinBundle then
        local ownedScene = false
        for i, v in ipairs(data.rewards) do
            local goodsType = GoodsUtils.GetIdType(v.goodsId)
            if goodsType == Constants.IDType.Live3DGoods then
                ownedScene = GoodsUtils.GetThingNo(data.icon) > 0
                break
            end
        end
        local ownedSkin = CardSkinComponent:IsHasSkin(data.icon)
        isOwned = ownedSkin or ownedScene
    elseif storeType == OverseaStoreConstants.StoreType.SkinScene then
        local num = GoodsUtils.GetThingNo(data.icon)
        isOwned = num > 0
    end
    
    CfUtils.SetActive(self.TxtTips, storeType == OverseaStoreConstants.StoreType.SkinBundle)

    if isOwned then
        CfUtils.SetActive(self.BtnDirectPurchase, false)
        CfUtils.SetActive(self.UIFX_DiscountedPrice_Button, false)
        CfUtils.SetActive(self.Discount, false)
        if storeType == OverseaStoreConstants.StoreType.SkinBundle then
            CfUtils.SetActive(self.FontStyleButton, false)
        else
            CfUtils.SetActive(self.FontStyleButton, true)
        end
        return
    else
        CfUtils.SetActive(self.BtnDirectPurchase, true)
        CfUtils.SetActive(self.FontStyleButton, false)
        CfUtils.SetActive(self.Discount, true)
    end

    if checkInt(data.price) > 0 then
        -- 直充
        if checkInt(data.original) ~= 0 then
            CfUtils.SetActive(self.OriginalPrice, true)
            CfUtils.SetActive(self.OriginalPriceImgIcon, false)
            CfUtils.FillText(self.OriginalPriceTextNumber, CfUtils.GetCustomDisplayPrice(data.original, nil, 24))
        else
            CfUtils.SetActive(self.OriginalPrice, false)
        end
        CfUtils.SetActive(self.DisCurrentPriceImgIcon, false)
        local windowsPriceId =  CfUtils.GetWindowsPriceId(data)
        CfUtils.FillText(self.NowPriceTextNumber, CfUtils.GetCustomDisplayPrice(windowsPriceId , data.channelProductId, 26))
        CfUtils.SetActive(self.NowPriceImgIcon, false)
    else
        -- 道具
        local goodsId = checkNumber(data.prices[1].currency)
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if checkInt(data.prices[1].original) ~= 0 then
            CfUtils.SetActive(self.OriginalPrice, true)
            CfUtils.SetActive(self.OriginalPriceImgIcon, true)
            CfUtils.FillImage(self.OriginalPriceImgIcon, goodsVo.photoPath)
            CfUtils.FillText(self.OriginalPriceTextNumber, data.prices[1].original)
        else
            CfUtils.SetActive(self.OriginalPrice, false)
        end
        CfUtils.SetActive(self.NowPriceImgIcon, true)
        CfUtils.FillImage(self.NowPriceImgIcon, goodsVo.photoPath)
        CfUtils.FillText(self.NowPriceTextNumber, data.prices[1].current)
    end

    -- 折扣
    if checkNumber(data.iconTitle) > 0 then
        CfUtils.SetActive(self.DiscountUnlock, true)
        CfUtils.FillText(self.DiscountUnlockTxtNumber, string.format('-%s%%', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.UIFX_DiscountedPrice_Button, true)
    else
        CfUtils.SetActive(self.DiscountUnlock, false)
        CfUtils.SetActive(self.UIFX_DiscountedPrice_Button, false)
    end
end

---刷新剩余时间
function OverseaStoreSkinCommonNode:RefreshTimeGroup()
    local data = self:GetProducts()[self:GetSelectedTabIdx()]
    local seconds = checkInt(data.endTime)
    if seconds <= 0 then
        CfUtils.SetActive(self.Time, false)
        return
    end
    
    CfUtils.SetActive(self.Time, true)
    self:UpdateTimeGroupText(data)
end

---更新剩余时间显示
function OverseaStoreSkinCommonNode:UpdateTimeGroupText(data)
    local seconds = checkInt(data.endTime)
    if seconds <= 0 then return end

    CfUtils.FillText(self.TimeTextDesc, CfUtils.GetTimeHMS4(seconds))
end

---开启定时器
function OverseaStoreSkinCommonNode:StartTimer()
    TimerModule.Instance:AddTimer(self:GetTimerName(), 0, 1, Bind(self, self.OnUpdate))
end

---停止定时器
function OverseaStoreSkinCommonNode:CloseTimer()
    TimerModule.Instance:RemoveTimer(self:GetTimerName())
end
